ipIsInWildCardNoCheck.body:
public static boolean ipIsInWildCardNoCheck(String ipWildCard, String ip) {
    String[] s1 = ipWildCard.split("\\.");
    String[] s2 = ip.split("\\.");
    boolean isMatchedSeg = true;
    for (int i = 0; i < s1.length && !s1[i].equals("*"); i++) {
        if (!s1[i].equals(s2[i])) {
            isMatchedSeg = false;
            break;
        }
    }
    return isMatchedSeg;
}

